import{_ as a,a as t,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const b=JSON.parse('{"title":"第二册：实践与进步 · Lesson 13 The Greenwood Boys","description":"学习 将来进行时与过程，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第二册：实践与进步 · Lesson 13 The Greenwood Boys","description":"学习 将来进行时与过程，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第2册课时","summary":"学习 将来进行时与过程，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · Lesson 12 Goodbye and good luck","link":"/life/english/new-concept/book-2/unit-01/lesson-012"},"next":{"text":"第二册：实践与进步 · Lesson 14 Do you speak English?","link":"/life/english/new-concept/book-2/unit-01/lesson-014"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · Lesson 12 Goodbye and good luck","link":"/life/english/new-concept/book-2/unit-01/lesson-012"},"next":{"text":"第二册：实践与进步 · Lesson 14 Do you speak English?","link":"/life/english/new-concept/book-2/unit-01/lesson-014"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-01/lesson-013.md","filePath":"life/english/new-concept/book-2/unit-01/lesson-013.md"}'),i={name:"life/english/new-concept/book-2/unit-01/lesson-013.md"};function l(r,e,s,h,d,c){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第二册-实践与进步-·-lesson-13-the-greenwood-boys" tabindex="-1">第二册：实践与进步 · Lesson 13 The Greenwood Boys <a class="header-anchor" href="#第二册-实践与进步-·-lesson-13-the-greenwood-boys" aria-label="Permalink to &quot;第二册：实践与进步 · Lesson 13 The Greenwood Boys&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-01/overview">单元 1</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>地方乐队即将演出，排练和正式演出时间不同；练习以未来时刻观察正在进行的活动。本课的语言观察是：will be rehearsing 只说明明晚七点的过程，不说明排练什么时候结束。要表达完成时间，应另外给出 finish 或完成时结构。完成学习后，请写三句演出日程，分别交代排练、开门和开演时间。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>band</td><td>/bænd/</td><td>n.</td><td>乐队</td><td>a local band</td></tr><tr><td>concert</td><td>/ˈkɒnsət/</td><td>n.</td><td>音乐会</td><td>give a concert</td></tr><tr><td>audience</td><td>/ˈɔːdiəns/</td><td>n.</td><td>观众</td><td>a small audience</td></tr><tr><td>rehearse</td><td>/rɪˈhɜːs/</td><td>v.</td><td>排练</td><td>rehearse a song</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>give a concert — 举办一场音乐会</li><li>at that time — 在那个时候，需有清楚的时间参照</li></ul><h2 id="语法讲解-将来进行时与过程" tabindex="-1">语法讲解：将来进行时与过程 <a class="header-anchor" href="#语法讲解-将来进行时与过程" aria-label="Permalink to &quot;语法讲解：将来进行时与过程&quot;">​</a></h2><p>将来进行时使用 will be 加动词 -ing，突出未来某个时间正在发生的过程，常用于说明正常安排中的活动。它与 will do 的区别主要是观察角度：一个看过程，一个把动作看成整体。句中须有明确或可推知的未来参照时间。不要把 will be 后面接原形误当进行时，也不要用它保证某项活动一定完成；完成结果需要其他表达。本课应用：will be rehearsing 只说明明晚七点的过程，不说明排练什么时候结束。要表达完成时间，应另外给出 finish 或完成时结构。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>At seven tomorrow, the band will be rehearsing in the hall.</p></blockquote><p>明天七点，乐队将在大厅里排练。</p><p>At seven tomorrow 建立未来参照点，will be rehearsing 表示该时刻正在进行的活动，in the hall 是地点。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>will rehearsing 缺少 be；will be rehearse 的动词形式也不对。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>在 will be rehearsing 中弱读 will be，重读 rehearsing；比较 seven 与 eight。可朗读本页原创示范并自行录音回听；本页不提供教材录音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>At seven tomorrow, the band will be rehearsing in the hall. The doors will open at eight. The first song will begin at half past eight.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写三句演出日程，分别交代排练、开门和开演时间。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句的组织方式：At seven tomorrow 建立未来参照点，will be rehearsing 表示该时刻正在进行的活动，in the hall 是地点。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：will rehearsing 缺少 be；will be rehearse 的动词形式也不对。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>补全将来进行时：The band will ___ rehearsing at seven.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> be</p><p><strong>解析：</strong> 将来进行时结构为 will be doing。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>观众几点可以入场？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> At eight.</p><p><strong>解析：</strong> doors will open 的时间是八点，不是第一首歌开始的八点半。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>把 They rehearse 改为“明天此时他们将正在排练”。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> They will be rehearsing at this time tomorrow.</p><p><strong>解析：</strong> 未来明确时刻的过程使用 will be doing。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：将来进行时与过程。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-2/unit-01/grammar">单元语法</a> · <a href="/life/english/new-concept/book-2/unit-01/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-2/unit-01/review">单元自测</a></p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-012">上一课</a> · <a href="/life/english/new-concept/book-2/unit-01/overview">单元目录</a> · <a href="/life/english/new-concept/book-2/unit-01/lesson-014">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const u=a(i,[["render",l]]);export{b as __pageData,u as default};
